import * as types from '../../../../actions/types.js'
import axios from 'axios'

import Site from '../../../../lib/site'

const fetchData = (params) => {
    const url = Site.resolveClientUrl('api/BettingTicketCenter/GetByRefNo');
    return axios.post(url, params.data, {
        headers: {
            'X-Requested-With': 'XMLHttpRequest',
            '__RequestVerificationToken': Site.getXsrfToken()
        }
    });
}

export function getGridData(params) {
    return (dispatch) => {
        fetchData(params).then(response => {
            dispatch(setGridData(response.data));
        });
    };
}

export function exportExcel(params) {
    return () => {
        return axios({
                url: Site.resolveClientUrl('api/BettingTicketCenter/GetByRefNo'),
                method: 'POST',
                responseType: 'blob', // important
                data: params.data,
                headers: {
                    'X-Requested-With': 'XMLHttpRequest',
                    '__RequestVerificationToken': Site.getXsrfToken()
                }
            });
    };
}

export function setGridData(data) {
    return {
        type: types.SET_GRID_DATA,
        data: data
    };
}


